function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 12) return 'nums needs 1 to 12 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1e9)) return 'Each value is a whole number from 0 to 10^9.';
  return null;
}

