function numSquarefulPerms(nums) {
  const isSquare = (value) => {
    const root = Math.floor(Math.sqrt(value));
    return root * root === value;
  };
  const count = new Map();
  for (const num of nums) {
    count.set(num, (count.get(num) || 0) + 1);
  }
  const values = [...count.keys()];
  const neighbors = new Map();
  for (const value of values) {
    neighbors.set(value, values.filter((other) => isSquare(value + other)));
  }
  let total = 0;
  const backtrack = (last, placed) => {
    if (placed === nums.length) {
      total++;
      return;
    }
    for (const next of neighbors.get(last)) {
      if (count.get(next) === 0) continue;
      count.set(next, count.get(next) - 1);
      backtrack(next, placed + 1);
      count.set(next, count.get(next) + 1);
    }
  };
  for (const start of values) {
    count.set(start, count.get(start) - 1);
    backtrack(start, 1);
    count.set(start, count.get(start) + 1);
  }
  return total;
}

