function numSquarefulPerms(nums) {
  // Count orderings of the positions with a bitmask DP, then divide out the swaps of equal values.
  const n = nums.length;
  const square = (x) => Number.isInteger(Math.sqrt(x));
  const ways = Array.from({ length: 1 << n }, () => new Array(n).fill(0));
  for (let i = 0; i < n; i++) ways[1 << i][i] = 1;
  for (let mask = 1; mask < 1 << n; mask++) {
    for (let i = 0; i < n; i++) {
      if (!ways[mask][i]) continue;
      for (let j = 0; j < n; j++) {
        if (mask & (1 << j) || !square(nums[i] + nums[j])) continue;
        ways[mask | (1 << j)][j] += ways[mask][i];
      }
    }
  }
  let orderings = ways[(1 << n) - 1].reduce((a, b) => a + b, 0);
  const seen = {};
  for (const v of nums) {
    seen[v] = (seen[v] || 0) + 1;
    orderings /= seen[v];
  }
  return orderings;
}

