function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const n = size === 'large' ? 12 : 1 + pick(7);
  const limit = size === 'large' ? (rand() < 0.5 ? 1e9 : 200) : (rand() < 0.5 ? 40 : 1e9);
  // Build a chain whose neighbours sum to squares so that answers are often non-zero.
  const nums = [pick(Math.min(limit, 50) + 1)];
  while (nums.length < n) {
    const last = nums[nums.length - 1];
    const roll = size === 'large' ? 1 : rand();
    if (roll < 0.15) { nums.push(last); continue; }
    if (roll < 0.3) { nums.push(pick(limit + 1)); continue; }
    const low = Math.ceil(Math.sqrt(last));
    const high = Math.floor(Math.sqrt(last + limit));
    const root = low + pick(high - low + 1);
    nums.push(root * root - last);
  }
  for (let i = n - 1; i > 0; i--) {
    const j = pick(i + 1);
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
